WATCH_STEPS = 40   # agent_0: steps to stay in the watch position after seeing partner with plate/dish


def _j(x):
    return jnp.asarray(x, dtype=jnp.int32)


# ----------------------------------------------------------------------------
# Generic helpers (JAX)
# ----------------------------------------------------------------------------
def localize(obs, exp):
    stat = obs[:, :, 20:29]
    diff = jnp.abs(exp - stat[None]).sum(axis=(1, 2, 3))
    return jnp.argmin(diff).astype(jnp.int32)


def facing_act(obs):
    return _j(T_FACE_TO_ACT)[jnp.argmax(obs[2, 2, 1:5])]


def held_type(vec):
    """vec = 5-vector [plate, cooked, i0, i1, i2] -> -1 none, 0..2 ingredient, 3 plate, 4 dish."""
    plate, cooked = vec[0], vec[1]
    ing = vec[2:5]
    n_ing = ing.sum()
    t = jnp.where(n_ing > 0, jnp.argmax(ing), -1)
    t = jnp.where((plate > 0) & (cooked == 0), 3, t)
    t = jnp.where(cooked > 0, 4, t)
    return t.astype(jnp.int32)


def read_cell(obs, pr, pc, gr, gc):
    lr = gr - pr + 2
    lc = gc - pc + 2
    vis = (lr >= 0) & (lr < 5) & (lc >= 0) & (lc < 5)
    vals = obs[jnp.clip(lr, 0, 4), jnp.clip(lc, 0, 4)]
    return jnp.where(vis, vals, 0), vis


def go_interact(pos, face, f_idx, d_act, nxt, interact=A_INTERACT):
    at = pos == f_idx
    return jnp.where(at, jnp.where(face == d_act, interact, d_act), nxt[pos, f_idx]).astype(jnp.int32)


def best_option(pos, face, f_arr, d_arr, valid, dist, nxt, interact=A_INTERACT, extra=0):
    turn = ((pos == f_arr) & (face != d_arr)).astype(jnp.int32)
    cost = jnp.where(valid, 2 * dist[pos, f_arr] + turn + extra, 9999)
    k = jnp.argmin(cost)
    return go_interact(pos, face, f_arr[k], d_arr[k], nxt, interact), valid.any()


def counter_states(obs, pr, pc):
    """Returns (code[4], vis[4]) code: -1 invisible, 0 empty, 1..3 raw ingredient k+1, 4 other."""
    ctr = _j(T_COUNTERS)
    codes = []
    viss = []
    for i in range(4):
        vals, vis = read_cell(obs, pr, pc, ctr[i, 0], ctr[i, 1])
        item = vals[29:34]
        ht = held_type(item)
        code = jnp.where(ht < 0, 0, jnp.where(ht <= 2, ht + 1, 4))
        codes.append(jnp.where(vis, code, -1))
        viss.append(vis)
    return jnp.stack(codes).astype(jnp.int32), jnp.stack(viss)


# ----------------------------------------------------------------------------
# agent_0 : outer ring ferry
# memory: [t, known, rtype, c0, c1, c2, c3, spare]
# ----------------------------------------------------------------------------
def init_agent_0():
    return jnp.zeros((36,), dtype=jnp.int32)


def agent_0_act(obs, reset, memory, rng):
    mem = jnp.where(reset, init_agent_0(), memory)
    t, known, rtype = mem[0], mem[1], mem[2]
    ctr_mem = mem[3:7]
    watch, dish_seen, placed = mem[7], mem[8], mem[9]
    dump_mem = mem[12:36]

    ring_rc = _j(T_RING_RC)
    ring_dist = _j(T_RING_DIST)
    ring_next = _j(T_RING_NEXT)

    pos = localize(obs, _j(T_RING_EXP))
    pr, pc = ring_rc[pos, 0], ring_rc[pos, 1]
    face = facing_act(obs)
    held = held_type(obs[2, 2, 5:10])

    # recipe from any visible always-on indicator
    rmask = obs[:, :, 23] > 0
    disp = (obs[:, :, 36:39] * rmask[:, :, None]).sum(axis=(0, 1))
    r_seen = disp.sum() > 0
    known = jnp.where(r_seen, 1, known).astype(jnp.int32)
    rtype_new = jnp.where(r_seen, jnp.argmax(disp), rtype).astype(jnp.int32)
    recipe_changed = rtype_new != rtype
    rtype = rtype_new

    codes, vis = counter_states(obs, pr, pc)
    ctr = jnp.where(vis, codes, ctr_mem).astype(jnp.int32)

    # partner observation: plate/dish -> cooking phase, move to the watch cell (4,1);
    # dish seen then gone -> delivery happened, grab the (possibly new) recipe ingredient now
    p_vis = obs[:, :, 10].sum() > 0
    p_held = held_type(obs[:, :, 15:20].sum(axis=(0, 1)))
    watch = jnp.where(p_vis & (p_held >= 3), WATCH_STEPS, jnp.maximum(watch - 1, 0)).astype(jnp.int32)
    dish_seen = jnp.where(p_vis & (p_held == 4), 1, dish_seen).astype(jnp.int32)
    trigger = (dish_seen > 0) & p_vis & (p_held != 4) & (watch > 0)
    watch = jnp.where(trigger, 0, watch).astype(jnp.int32)
    # one stock placement per cycle: cleared by observed delivery, recipe change, or timeout
    placed = jnp.where(trigger | recipe_changed, 0, jnp.maximum(placed - 1, 0)).astype(jnp.int32)
    dish_seen = jnp.where(watch == 0, 0, dish_seen).astype(jnp.int32)
    # cooking phase: keep pass-through counters empty so nothing stale is there at delivery
    cleanup = watch > 0

    match_code = rtype + 1
    is_match = ctr == match_code
    is_stale = (ctr >= 1) & (ctr <= 3) & (~is_match)
    n_match = is_match.sum()

    rctr_f = _j(T_RCTR_F)
    rctr_d = _j(T_RCTR_D)

    # place held matching ingredient on first empty counter by preference
    pref = _j(T_CTR_PREF)[rtype]
    empty_pref = ctr[pref] == 0
    first_k = jnp.argmax(empty_pref)
    tgt = pref[first_k]
    any_empty = empty_pref.any()
    a_place = go_interact(pos, face, rctr_f[tgt], rctr_d[tgt], ring_next)
    a_place = jnp.where(any_empty, a_place, ring_next[pos, jnp.where(watch > 0, T_WATCH_CELL, _j(T_IDLE)[rtype])])

    # dump on nearest free wall
    dump_f = _j(T_DUMP_F)
    dump_d = _j(T_DUMP_D)
    dump_w = _j(T_DUMP_W)
    occ = []
    for i in range(len(T_DUMP_F)):
        vals, v = read_cell(obs, pr, pc, dump_w[i, 0], dump_w[i, 1])
        occ.append(jnp.where(v, (vals[29:34].sum() > 0).astype(jnp.int32), dump_mem[i]))
    occ = jnp.stack(occ).astype(jnp.int32)
    dump_mem = occ
    occ = occ > 0
    a_dump, _ = best_option(pos, face, dump_f, dump_d, ~occ, ring_dist, ring_next)

    # remove nearest stale counter ingredient
    a_clean, any_stale = best_option(pos, face, rctr_f, rctr_d, is_stale, ring_dist, ring_next)
    is_raw = (ctr >= 1) & (ctr <= 3)
    a_clean_any, any_raw = best_option(pos, face, rctr_f, rctr_d, is_raw, ring_dist, ring_next)

    # fetch matching ingredient from supply
    a_fetch = go_interact(pos, face, _j(T_RSUP_F)[rtype], _j(T_RSUP_D)[rtype], ring_next)

    # idle spot: stand at the idle counter access cell and keep lifting / replacing the
    # matching item there so a partner observes a fresh placement after each delivery.
    idle_cell = jnp.where(watch > 0, T_WATCH_CELL, _j(T_IDLE)[rtype])
    idle_ctr = _j(T_IDLE_CTR)[rtype]
    at_idle = (pos == idle_cell) & (watch == 0)
    a_idle_move = ring_next[pos, idle_cell]
    a_toggle = go_interact(pos, face, rctr_f[idle_ctr], rctr_d[idle_ctr], ring_next)
    ictr_rc = _j(T_INNER_CTR_RC)[idle_ctr]
    p_vals, p_vis_cell = read_cell(obs, pr, pc, ictr_rc[0], ictr_rc[1])
    partner_at_ctr = p_vis_cell & (p_vals[10] > 0)
    a_idle = jnp.where(at_idle & (ctr[idle_ctr] == match_code),
                       jnp.where(partner_at_ctr, A_STAY, a_toggle), a_idle_move)

    # unknown recipe: head toward (4,1) which reveals an indicator on the way
    a_explore = ring_next[pos, T_EXPLORE_CELL]

    holding_match = (held == rtype) & (known > 0) & (~cleanup)
    holding_other = (held >= 0) & (~holding_match)
    a_hold = a_place
    empty_action = jnp.where(trigger | ((n_match < CAP) & (~cleanup) & (placed == 0)), a_fetch,
                             jnp.where(cleanup & any_raw, a_clean_any,
                                       jnp.where(any_stale, a_clean, a_idle)))
    action = jnp.where(holding_match, a_hold,
                       jnp.where(holding_other, a_dump, empty_action))
    placing_now = holding_match & (~cleanup) & (action == A_INTERACT)
    placed = jnp.where(placing_now, PLACED_STEPS, placed).astype(jnp.int32)
    action = jnp.where(known > 0, action, a_explore).astype(jnp.int32)

    new_mem = jnp.concatenate([jnp.stack([t + 1, known, rtype]), ctr,
                               jnp.stack([watch, dish_seen, placed]), jnp.zeros((2,), jnp.int32),
                               dump_mem]).astype(jnp.int32)
    trace = {'pos_r': pr, 'pos_c': pc, 'held': held, 'rtype': rtype, 'known': known,
             'n_match': n_match.astype(jnp.int32), 'action': action, 'watch': watch, 'trig': trigger}
    return action, new_mem, trace


# ----------------------------------------------------------------------------
# agent_1 : inner cook
# memory: [t, known, rtype, t_ref, stale0..stale3]
# ----------------------------------------------------------------------------
def init_agent_1():
    return jnp.zeros((10,), dtype=jnp.int32)


def agent_1_act(obs, reset, memory, rng):
    mem = jnp.where(reset, init_agent_1(), memory)
    t, known, rtype, t_ref = mem[0], mem[1], mem[2], mem[3]
    stale = mem[4:8]
    p_empty_seen = mem[8]
    ferry_seen = mem[9]

    inner_rc = _j(T_INNER_RC)
    inner_dist = _j(T_INNER_DIST)
    inner_next = _j(T_INNER_NEXT)

    pos = localize(obs, _j(T_INNER_EXP))
    pr, pc = inner_rc[pos, 0], inner_rc[pos, 1]
    face = facing_act(obs)
    held = held_type(obs[2, 2, 5:10])

    # button display evidence (inner room never sees the always-on indicator)
    disp = obs[:, :, 36:39].sum(axis=(0, 1))
    b_seen = disp.sum() > 0
    btype = jnp.argmax(disp).astype(jnp.int32)

    # counters
    codes, vis = counter_states(obs, pr, pc)
    has_item = codes > 0
    empty_vis = vis & (codes == 0)
    # first observation after a delivery: everything currently on counters may predate the
    # recipe resample -> mark stale; evidence is only trusted from the next observation on.
    first_after = t == t_ref
    stale = jnp.where(first_after, jnp.where(vis, has_item.astype(jnp.int32), 1), stale).astype(jnp.int32)
    stale = jnp.where(empty_vis & (~first_after), 0, stale).astype(jnp.int32)
    raw_ok = vis & (codes >= 1) & (codes <= 2)   # ingredient 0 or 1
    fresh = raw_ok & (stale == 0)
    any_fresh = fresh.any()
    fk = jnp.argmax(fresh)
    ftype = codes[fk] - 1

    # partner evidence: partner seen empty-handed since last delivery, now holding ingredient 0/1
    p_vis = obs[:, :, 10].sum() > 0
    p_held_vec = obs[:, :, 15:20].sum(axis=(0, 1))
    p_held = held_type(p_held_vec)
    p_empty_now = p_vis & (p_held < 0)
    p_empty_seen = jnp.where(first_after, 0, p_empty_seen).astype(jnp.int32)
    p_grab = p_vis & (p_held >= 0) & (p_held <= 1) & (p_empty_seen > 0) & (~first_after)
    p_empty_seen = jnp.where(p_empty_now, 1, p_empty_seen).astype(jnp.int32)
    any_fresh = any_fresh & (~first_after)

    ferry_seen = jnp.where(any_fresh | p_grab, 1, ferry_seen).astype(jnp.int32)
    known_new = (known > 0) | b_seen | any_fresh | p_grab
    rtype = jnp.where(b_seen, btype,
                      jnp.where(known > 0, rtype,
                                jnp.where(any_fresh, ftype,
                                          jnp.where(p_grab, p_held, rtype)))).astype(jnp.int32)
    known = known_new.astype(jnp.int32)

    # pot
    pot_vals, _ = read_cell(obs, pr, pc, 4, 4)
    pot_ing = pot_vals[31:34]
    pot_count = pot_ing.sum()
    pot_cooked = pot_vals[30] > 0
    pot_cooking = pot_vals[39] > 0
    pot_idle = (~pot_cooked) & (~pot_cooking)
    committed = pot_idle & (pot_count > 0)
    pot_type = jnp.argmax(pot_ing).astype(jnp.int32)
    need = jnp.where(committed, pot_type, rtype).astype(jnp.int32)
    have_info = (known > 0) | committed

    ones2 = jnp.ones((2,), dtype=bool)
    ones4 = jnp.ones((4,), dtype=bool)
    pot_f = _j(T_POT_F)
    pot_d = _j(T_POT_D)
    ictr_f = _j(T_ICTR_F)
    ictr_d = _j(T_ICTR_D)
    deliv_f = _j(T_DELIV_F)
    deliv_d = _j(T_DELIV_D)

    a_deliver, _ = best_option(pos, face, deliv_f, deliv_d, ones2, inner_dist, inner_next)
    a_pot_int, _ = best_option(pos, face, pot_f, pot_d, ones4, inner_dist, inner_next)
    a_pot_wait = go_interact(pos, face, deliv_f[0], A_RIGHT, inner_next, A_STAY)
    a_plate, _ = best_option(pos, face, _j(T_PLATE_F), _j(T_PLATE_D), ones2, inner_dist, inner_next)
    # ingredient sources: counters holding `need` (any staleness) + supply
    ctr_has_need = vis & (codes == need + 1)
    src_f = jnp.concatenate([ictr_f, _j(T_ISUP_F)[need][None]])
    src_d = jnp.concatenate([ictr_d, _j(T_ISUP_D)[need][None]])
    src_valid = jnp.concatenate([ctr_has_need, (need <= 1)[None]])
    # counters carry a +1 bias: use one only when strictly closer than the supply (stable choice)
    src_extra = jnp.concatenate([jnp.ones((4,), jnp.int32), jnp.zeros((1,), jnp.int32)])
    a_get_ing, _ = best_option(pos, face, src_f, src_d, src_valid, inner_dist, inner_next, extra=src_extra)
    a_button, _ = best_option(pos, face, _j(T_BTN_F), _j(T_BTN_D), ones2, inner_dist, inner_next)
    a_wait = inner_next[pos, T_WAIT_CELL]
    a_drop, any_drop = best_option(pos, face, ictr_f, ictr_d, empty_vis, inner_dist, inner_next)
    a_drop = jnp.where(any_drop, a_drop, a_pot_wait)

    wait_limit = jnp.where(t_ref == 0, T_WAIT_START, jnp.where(ferry_seen > 0, T_WAIT, T_WAIT_NOFERRY))
    go_button = (t - t_ref) >= (wait_limit - 3)

    pot_accepts = pot_idle & (pot_count < 3) & ((pot_count == 0) | (pot_type == held))

    empty_action = jnp.where(pot_cooked | pot_cooking, a_plate,
                             jnp.where(have_info, a_get_ing,
                                       jnp.where(go_button, a_button, a_wait)))
    action = jnp.where(held == 4, a_deliver,
                       jnp.where(held == 3, jnp.where(pot_cooked, a_pot_int, jnp.where(pot_cooking, a_pot_wait, a_drop)),
                                 jnp.where(held >= 0, jnp.where(pot_accepts, a_pot_int, a_drop),
                                           empty_action))).astype(jnp.int32)

    # delivery bookkeeping
    at_deliv = ((pos == deliv_f[0]) & (face == deliv_d[0])) | ((pos == deliv_f[1]) & (face == deliv_d[1]))
    delivered = (held == 4) & at_deliv & (action == A_INTERACT)
    known = jnp.where(delivered, 0, known).astype(jnp.int32)
    t_ref = jnp.where(delivered, t + 1, t_ref).astype(jnp.int32)

    new_mem = jnp.concatenate([jnp.stack([t + 1, known, rtype, t_ref]), stale,
                               jnp.stack([p_empty_seen, ferry_seen])]).astype(jnp.int32)
    trace = {'pos_r': pr, 'pos_c': pc, 'held': held, 'rtype': rtype, 'known': known,
             'pot_count': pot_count.astype(jnp.int32), 'action': action, 'delivered': delivered}
    return action, new_mem, trace
